import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    teacher_logits = torch.stack((features[0], -features[0], features[1]))
    return {"inputs": synth.Tensor(features), "labels": int(features[:3].argmax()), "teacher_logits": synth.Tensor(teacher_logits)}
class DistillationModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, inputs):
        return {"student_logits": self.network(inputs)}
ds = synth.Spec("dkd-data", generator=samples, size=12, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
trainer = Trainer(DistillationModel(), train, recipe="structured-objective", recipe_config={"loss": "dkd", "loss_kwargs": {"alpha": 1.0, "beta": 1.0, "temperature": 2.0}, "bindings": {"logits_or_prediction": {"output": "student_logits"}, "targets": {"batch": "labels"}, "teacher_logits": {"batch": "teacher_logits"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
